namespace ZoneEngine.Core.Arete.Quests
{
    using System;
    using AORebirth.Core.Entities;
    using AORebirth.Core.Network;
    using ZoneEngine.Core.Controllers;

    /// <summary>Capture 20260721-Mason QuestFullUpdate wire tips (patched player + fixed mission ids).</summary>
    internal static class DoctorMasonTipSender
    {
        private const int AssembleImplant1Instance = unchecked((int)0x555BE9FD);
        private const int AssembleImplant2Instance = unchecked((int)0x555BE9FE);
        private const int AssembleImplant3Instance = unchecked((int)0x555BE9FF);
        private const int ShowDrMasonImplantInstance = unchecked((int)0x555BEA00);
        private const int InstallTheImplantInstance = unchecked((int)0x555BEA01);
        private const int TalkToDoctorMasonAfterInstallInstance = unchecked((int)0x555BEA02);
        private const int TalkToLoreleiInstance = unchecked((int)0x555BEA03);

        public static RexQuestPreviewEmissionResult TrySendTalkToDoctorMasonToAssemble1Handoff(ICharacter source)
        {
            return Handoff(source, unchecked((int)0x555BE9FC), SendAssembleImplant1Tip, "TalkMason→Assemble1", "Mission:555BE9FD");
        }

        public static RexQuestPreviewEmissionResult TrySendAssemble1ToAssemble2Handoff(ICharacter source)
        {
            return Handoff(source, AssembleImplant1Instance, SendAssembleImplant2Tip, "Assemble1→Assemble2", "Mission:555BE9FE");
        }

        public static RexQuestPreviewEmissionResult TrySendAssemble2ToAssemble3Handoff(ICharacter source)
        {
            return Handoff(source, AssembleImplant2Instance, SendAssembleImplant3Tip, "Assemble2→Assemble3", "Mission:555BE9FF");
        }

        public static RexQuestPreviewEmissionResult TrySendAssemble3ToShowHandoff(ICharacter source)
        {
            return Handoff(source, AssembleImplant3Instance, SendShowDrMasonImplantTip, "Assemble3→Show", "Mission:555BEA00");
        }

        public static RexQuestPreviewEmissionResult TrySendShowToInstallHandoff(ICharacter source)
        {
            return Handoff(source, ShowDrMasonImplantInstance, SendInstallTheImplantTip, "Show→Install", "Mission:555BEA01");
        }

        public static RexQuestPreviewEmissionResult TrySendInstallToTalkMasonHandoff(ICharacter source)
        {
            return Handoff(source, InstallTheImplantInstance, SendTalkToDoctorMasonAfterInstallTip, "Install→TalkMason", "Mission:555BEA02");
        }

        public static RexQuestPreviewEmissionResult TrySendTalkMasonToLoreleiHandoff(ICharacter source)
        {
            return Handoff(source, TalkToDoctorMasonAfterInstallInstance, SendTalkToLoreleiTip, "TalkMason→Lorelei", "Mission:555BEA03");
        }

        public static RexQuestPreviewEmissionResult TrySendAssembleImplant1TipOnly(ICharacter source)
        {
            return TipOnly(source, SendAssembleImplant1Tip, "AssembleImplant1", "Mission:555BE9FD");
        }

        public static RexQuestPreviewEmissionResult TrySendAssembleImplant2TipOnly(ICharacter source)
        {
            return TipOnly(source, SendAssembleImplant2Tip, "AssembleImplant2", "Mission:555BE9FE");
        }

        public static RexQuestPreviewEmissionResult TrySendAssembleImplant3TipOnly(ICharacter source)
        {
            return TipOnly(source, SendAssembleImplant3Tip, "AssembleImplant3", "Mission:555BE9FF");
        }

        public static RexQuestPreviewEmissionResult TrySendShowDrMasonImplantTipOnly(ICharacter source)
        {
            return TipOnly(source, SendShowDrMasonImplantTip, "ShowDrMasonImplant", "Mission:555BEA00");
        }

        public static RexQuestPreviewEmissionResult TrySendInstallTheImplantTipOnly(ICharacter source)
        {
            return TipOnly(source, SendInstallTheImplantTip, "InstallTheImplant", "Mission:555BEA01");
        }

        public static RexQuestPreviewEmissionResult TrySendTalkToDoctorMasonAfterInstallTipOnly(ICharacter source)
        {
            return TipOnly(source, SendTalkToDoctorMasonAfterInstallTip, "TalkToDoctorMasonAfterInstall", "Mission:555BEA02");
        }

        public static RexQuestPreviewEmissionResult TrySendTalkToLoreleiTipOnly(ICharacter source)
        {
            return TipOnly(source, SendTalkToLoreleiTip, "TalkToLorelei", "Mission:555BEA03");
        }

        private static void SendAssembleImplant1Tip(ICharacter source)
        {
            TrySendWire(source, "", unchecked((int)0x555CF6A7), AssembleImplant1Instance);
        }

        private static void SendAssembleImplant2Tip(ICharacter source)
        {
            TrySendWire(source, "", unchecked((int)0x555CF6AD), AssembleImplant2Instance);
        }

        private static void SendAssembleImplant3Tip(ICharacter source)
        {
            TrySendWire(source, "", unchecked((int)0x555CF6AE), AssembleImplant3Instance);
        }

        private static void SendShowDrMasonImplantTip(ICharacter source)
        {
            TrySendWire(source, "", unchecked((int)0x555CF6AF), ShowDrMasonImplantInstance);
        }

        private static void SendInstallTheImplantTip(ICharacter source)
        {
            TrySendWire(source, "", unchecked((int)0x555CF6B1), InstallTheImplantInstance);
        }

        private static void SendTalkToDoctorMasonAfterInstallTip(ICharacter source)
        {
            TrySendWire(source, "", unchecked((int)0x555CF6B5), TalkToDoctorMasonAfterInstallInstance);
        }

        private static void SendTalkToLoreleiTip(ICharacter source)
        {
            TrySendWire(source, "", unchecked((int)0x555CF6B6), TalkToLoreleiInstance);
        }


        private static RexQuestPreviewEmissionResult Handoff(
            ICharacter source,
            int deleteMissionInstance,
            Action<ICharacter> sendTip,
            string label,
            string questId)
        {
            if (source?.Controller?.Client == null)
            {
                return RexQuestPreviewEmissionResult.Failed(label + " skipped: client missing.");
            }

            try
            {
                SafeQuestFullUpdateSender.SendTipAction59AndDelete(source, deleteMissionInstance);
                sendTip(source);
                return RexQuestPreviewEmissionResult.Sent(
                    label + " tip. mission=" + questId + " source=20260721-Mason");
            }
            catch (Exception e)
            {
                return RexQuestPreviewEmissionResult.Failed(label + " failed: " + e.Message);
            }
        }

        private static RexQuestPreviewEmissionResult TipOnly(
            ICharacter source,
            Action<ICharacter> sendTip,
            string label,
            string questId)
        {
            if (source?.Controller?.Client == null)
            {
                return RexQuestPreviewEmissionResult.Failed(label + " tip skipped: client missing.");
            }

            try
            {
                sendTip(source);
                return RexQuestPreviewEmissionResult.Sent(
                    label + " tip-only. mission=" + questId + " source=20260721-Mason");
            }
            catch (Exception e)
            {
                return RexQuestPreviewEmissionResult.Failed(label + " tip-only failed: " + e.Message);
            }
        }

        private static void TrySendWire(ICharacter source, string hex, int capturedMission, int fixedMission)
        {
            ZoneClient client = source?.Controller?.Client as ZoneClient;
            if (client == null || source.Identity.Instance == 0)
            {
                return;
            }

            const int capturedPlayer = unchecked((int)0x797E306A);
            byte[] packet = HexToBytes(hex);
            ReplaceInt32Be(packet, capturedPlayer, source.Identity.Instance);
            ReplaceInt32Be(packet, capturedMission, fixedMission);
            client.EnqueueOutboundCompressedBuffer(packet);
        }

        private static byte[] HexToBytes(string hex)
        {
            byte[] bytes = new byte[hex.Length / 2];
            for (int i = 0; i < bytes.Length; i++)
            {
                bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            }

            return bytes;
        }

        private static void ReplaceInt32Be(byte[] packet, int from, int to)
        {
            byte b0 = (byte)(from >> 24);
            byte b1 = (byte)(from >> 16);
            byte b2 = (byte)(from >> 8);
            byte b3 = (byte)from;
            for (int i = 0; i + 4 <= packet.Length; i++)
            {
                if (packet[i] == b0 && packet[i + 1] == b1 && packet[i + 2] == b2 && packet[i + 3] == b3)
                {
                    packet[i] = (byte)(to >> 24);
                    packet[i + 1] = (byte)(to >> 16);
                    packet[i + 2] = (byte)(to >> 8);
                    packet[i + 3] = (byte)to;
                    i += 3;
                }
            }
        }
    }
}
